<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { ArchiveRestore, Trash2 } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import { api, dateTimeLabel, loadProjects, messageOf, notify, query } from '../api'
import type { Page, TrashEntry } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[]}>();const items=ref<TrashEntry[]>([]),kind=ref(''),total=ref(0),offset=ref(0),error=ref(''),loading=ref(false),restoring=ref('');const limit=30
const names:Record<string,string>={projects:'项目',tasks:'任务',records:'记录',issues:'问题',worklogs:'日志',time_entries:'工时',reminders:'提醒'}
async function load(){loading.value=true;error.value='';try{const page=await api<Page<TrashEntry>>(`/api/trash?${query({kind:kind.value,limit,offset:offset.value})}`);items.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function restore(item:TrashEntry){restoring.value=item.id;try{await api(`/api/trash/${item.entity_type}/${item.id}/restore`,{method:'POST',body:JSON.stringify({version:item.version})});notify('已恢复');await loadProjects();emit('changed');await load()}catch(e){error.value=messageOf(e)}finally{restoring.value=''}}
onMounted(load);watch(()=>props.revision,load);watch(kind,()=>{offset.value=0;void load()});function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>回收站</h1><p class="page-description">误删的内容可以恢复。关联项目或上级任务须先恢复。</p></div><Trash2 :size="24" class="muted"/></div><div class="filter-bar"><select v-model="kind" aria-label="回收站类型"><option value="">全部类型</option><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select><span class="input-hint">此处不提供永久删除，附件随引用保留。</span></div><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div class="surface"><p v-if="loading" class="loading-message">正在读取回收站…</p><div v-else-if="!items.length" class="empty-state"><Trash2 :size="36"/><h2>回收站是空的</h2><p>移入回收站的项目资料会保留在这里。</p></div><div v-else class="table-scroll"><table><thead><tr><th>内容</th><th>类型</th><th>移入时间</th><th class="right">操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.entity_type+item.id"><td>{{item.title||item.name||item.content?.slice(0,80)||item.log_date||'无标题'}}</td><td>{{names[item.entity_type]||item.entity_type}}</td><td>{{dateTimeLabel(item.deleted_at)}}</td><td class="right"><button class="button subtle small" :disabled="!!restoring" @click="restore(item)"><ArchiveRestore :size="15"/>{{restoring===item.id?'正在恢复…':'恢复'}}</button></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></div></template>
